import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.D7WGirly.js";const b=JSON.parse('{"title":"Feature Auctions — Troubleshooting & FAQs","description":"","frontmatter":{},"headers":[],"relativePath":"feature-auctions-04-troubleshooting-and-faqs.md","filePath":"feature-auctions-04-troubleshooting-and-faqs.md"}'),o={name:"feature-auctions-04-troubleshooting-and-faqs.md"};function i(s,e,u,h,c,l){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="feature-auctions-—-troubleshooting-faqs" tabindex="-1">Feature Auctions — Troubleshooting &amp; FAQs <a class="header-anchor" href="#feature-auctions-—-troubleshooting-faqs" aria-label="Permalink to &quot;Feature Auctions — Troubleshooting &amp; FAQs&quot;">​</a></h1><p><em>Common issues, edge cases, and answers to frequent questions</em></p><hr><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="who-can-create-a-feature-auction" tabindex="-1">Who can create a Feature Auction? <a class="header-anchor" href="#who-can-create-a-feature-auction" aria-label="Permalink to &quot;Who can create a Feature Auction?&quot;">​</a></h3><p>Any workspace member can create a Feature Auction — it&#39;s not restricted to admins.</p><h3 id="do-buyers-need-a-lodestone-account" tabindex="-1">Do buyers need a Lodestone account? <a class="header-anchor" href="#do-buyers-need-a-lodestone-account" aria-label="Permalink to &quot;Do buyers need a Lodestone account?&quot;">​</a></h3><p>No. Buyers receive an email invitation with a unique link to the auction page. They can participate without creating a Lodestone account. This is by design — it removes friction and maximizes participation from stakeholders who aren&#39;t regular Lodestone users.</p><h3 id="can-i-give-different-buyers-different-wallet-amounts" tabindex="-1">Can I give different buyers different wallet amounts? <a class="header-anchor" href="#can-i-give-different-buyers-different-wallet-amounts" aria-label="Permalink to &quot;Can I give different buyers different wallet amounts?&quot;">​</a></h3><p>Yes. Wallet amounts are set individually for each buyer during auction setup. Use this to weight certain stakeholders&#39; input more heavily — for example, giving larger customers a proportionally bigger wallet, or giving an executive sponsor more budget than other participants.</p><h3 id="can-buyers-see-what-other-buyers-are-spending" tabindex="-1">Can buyers see what other buyers are spending? <a class="header-anchor" href="#can-buyers-see-what-other-buyers-are-spending" aria-label="Permalink to &quot;Can buyers see what other buyers are spending?&quot;">​</a></h3><p>No. Each buyer only sees their own wallet balance and their own purchases. Aggregate results and individual buyer activity are only visible to the auctioneer via the dashboard.</p><h3 id="can-buyers-leave-comments-or-feedback-when-purchasing-a-feature" tabindex="-1">Can buyers leave comments or feedback when purchasing a Feature? <a class="header-anchor" href="#can-buyers-leave-comments-or-feedback-when-purchasing-a-feature" aria-label="Permalink to &quot;Can buyers leave comments or feedback when purchasing a Feature?&quot;">​</a></h3><p>No. The auction is purchases only — there is no commentary or note field for buyers. If you want qualitative feedback alongside the auction, you&#39;ll need to gather it separately (e.g. via a follow-up survey or debrief conversation).</p><h3 id="can-i-add-buyers-or-features-after-the-auction-has-been-created" tabindex="-1">Can I add buyers or Features after the auction has been created? <a class="header-anchor" href="#can-i-add-buyers-or-features-after-the-auction-has-been-created" aria-label="Permalink to &quot;Can I add buyers or Features after the auction has been created?&quot;">​</a></h3><p>No. Both the buyer list and the Feature list are locked once the auction is created. Make sure both are final before you create the auction.</p><h3 id="can-i-change-a-buyer-s-wallet-amount-after-the-auction-has-started" tabindex="-1">Can I change a buyer&#39;s wallet amount after the auction has started? <a class="header-anchor" href="#can-i-change-a-buyer-s-wallet-amount-after-the-auction-has-started" aria-label="Permalink to &quot;Can I change a buyer&#39;s wallet amount after the auction has started?&quot;">​</a></h3><p>No. Wallet amounts are set at creation and cannot be modified once the auction is live.</p><h3 id="can-different-buyers-be-given-different-wallet-amounts" tabindex="-1">Can different buyers be given different wallet amounts? <a class="header-anchor" href="#can-different-buyers-be-given-different-wallet-amounts" aria-label="Permalink to &quot;Can different buyers be given different wallet amounts?&quot;">​</a></h3><p>Yes — wallet amounts are set individually per buyer during setup, so you have full control over how much budget each participant receives.</p><h3 id="are-buyers-reminded-before-the-auction-closes" tabindex="-1">Are buyers reminded before the auction closes? <a class="header-anchor" href="#are-buyers-reminded-before-the-auction-closes" aria-label="Permalink to &quot;Are buyers reminded before the auction closes?&quot;">​</a></h3><p>Yes. Buyers receive a reminder email before the auction ends, in addition to the initial invitation.</p><h3 id="what-happens-if-a-buyer-loses-their-invitation-email" tabindex="-1">What happens if a buyer loses their invitation email? <a class="header-anchor" href="#what-happens-if-a-buyer-loses-their-invitation-email" aria-label="Permalink to &quot;What happens if a buyer loses their invitation email?&quot;">​</a></h3><p>The auctioneer can resend the invitation link from the Auctioneer Dashboard at any time during the auction.</p><h3 id="can-i-cancel-an-auction-that-s-already-running" tabindex="-1">Can I cancel an auction that&#39;s already running? <a class="header-anchor" href="#can-i-cancel-an-auction-that-s-already-running" aria-label="Permalink to &quot;Can I cancel an auction that&#39;s already running?&quot;">​</a></h3><p>Yes. The auctioneer can cancel an in-progress auction from the dashboard. This is useful if you need to restart with different parameters — for example, if you realize a Feature was included by mistake or a key buyer wasn&#39;t added before the list locked.</p><h3 id="are-results-visible-to-buyers" tabindex="-1">Are results visible to buyers? <a class="header-anchor" href="#are-results-visible-to-buyers" aria-label="Permalink to &quot;Are results visible to buyers?&quot;">​</a></h3><p>No. Results are only visible to the auctioneer. If you want to share results with buyers or other stakeholders, export the CSV from the dashboard and distribute it manually.</p><h3 id="are-past-auctions-saved" tabindex="-1">Are past auctions saved? <a class="header-anchor" href="#are-past-auctions-saved" aria-label="Permalink to &quot;Are past auctions saved?&quot;">​</a></h3><p>Yes. Completed auctions remain accessible after they end. You can return to any past auction to review results, re-export the CSV, or reference participation data.</p><h3 id="do-auction-results-update-anything-in-lodestone-automatically" tabindex="-1">Do auction results update anything in Lodestone automatically? <a class="header-anchor" href="#do-auction-results-update-anything-in-lodestone-automatically" aria-label="Permalink to &quot;Do auction results update anything in Lodestone automatically?&quot;">​</a></h3><p>No. Auction results do not write back to Features, Roadmaps, or Strategies. Any changes to your plans based on auction results are made manually. This is intentional — the auction is an input to your judgment, not a replacement for it.</p><hr><h2 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h2><h3 id="a-buyer-says-they-didn-t-receive-their-invitation" tabindex="-1">A buyer says they didn&#39;t receive their invitation <a class="header-anchor" href="#a-buyer-says-they-didn-t-receive-their-invitation" aria-label="Permalink to &quot;A buyer says they didn&#39;t receive their invitation&quot;">​</a></h3><p>First, ask them to check their spam folder. If it&#39;s not there, resend the invitation from the Auctioneer Dashboard — there&#39;s a resend option available for each buyer.</p><h3 id="a-buyer-wants-to-change-their-purchases-but-the-auction-has-ended" tabindex="-1">A buyer wants to change their purchases but the auction has ended <a class="header-anchor" href="#a-buyer-wants-to-change-their-purchases-but-the-auction-has-ended" aria-label="Permalink to &quot;A buyer wants to change their purchases but the auction has ended&quot;">​</a></h3><p>Once the auction end time has passed, buyers can no longer make changes. If participation was low and you want to extend the window, you can adjust the end date from the dashboard while the auction is still active. Once it&#39;s ended, there&#39;s no way to reopen it for additional purchases.</p><h3 id="i-created-the-auction-with-the-wrong-features-or-buyers" tabindex="-1">I created the auction with the wrong Features or buyers <a class="header-anchor" href="#i-created-the-auction-with-the-wrong-features-or-buyers" aria-label="Permalink to &quot;I created the auction with the wrong Features or buyers&quot;">​</a></h3><p>Because the Feature list and buyer list are locked at creation, the only option is to cancel the current auction and create a new one with the correct parameters. Use the cancel option in the Auctioneer Dashboard.</p><h3 id="results-look-skewed-toward-one-or-two-buyers" tabindex="-1">Results look skewed toward one or two buyers <a class="header-anchor" href="#results-look-skewed-toward-one-or-two-buyers" aria-label="Permalink to &quot;Results look skewed toward one or two buyers&quot;">​</a></h3><p>This can happen when wallet amounts vary significantly across buyers — a buyer with a much larger wallet will naturally dominate total spend metrics. If this is a concern, check results using the <strong>quantity purchased</strong> view alongside total spend. Quantity purchased is less affected by wallet size and gives a better picture of how broadly a Feature was valued across all participants.</p><h3 id="the-opportunity-canvas-isn-t-showing-up-in-the-buyer-s-feature-modal" tabindex="-1">The Opportunity Canvas isn&#39;t showing up in the buyer&#39;s Feature modal <a class="header-anchor" href="#the-opportunity-canvas-isn-t-showing-up-in-the-buyer-s-feature-modal" aria-label="Permalink to &quot;The Opportunity Canvas isn&#39;t showing up in the buyer&#39;s Feature modal&quot;">​</a></h3><p>Opportunity Canvases only appear in the auction if they have been generated for that Feature in Lodestone before the auction was created. Check the Feature Detail page to confirm an Opportunity Canvas exists. If it doesn&#39;t, you can generate one and it should become available — though you may need to verify whether this updates an active auction in real time.</p><hr><p><em>This is version 1 of the Feature Auctions documentation, based on the Lodestone knowledge base from early 2025, updated with confirmed platform behavior.</em></p>',46)])])}const p=a(o,[["render",i]]);export{b as __pageData,p as default};
